from taf.internal.managedobject import ManagedObject
from taf.gnb.oam.coam.vdu.facade import VduConnection

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ManagedVduConnection(ManagedObject):
    """
    ManagedObject interface for VDU Connection.
    """
    _parameter_mapping = {"user": "username", "release": "vdu_version"}

    def __init__(
            self,
            vdu_connection_params,
            **kwargs):
        super(ManagedVduConnection, self).__init__(**kwargs)
        self._vdu_connection_params = vdu_connection_params.copy()
        for key, value in {'secure': True, 'port': ''}.items():
            self._vdu_connection_params.setdefault(key, value)
        self._vdu_connection = None

    @property
    def vdu_connection(self):
        return self._vdu_connection

    def _create_vdu_connection(
            self,
            vdu_connection_params):
        return VduConnection(
            **{self._parameter_mapping.get(k, k): v
               for k, v in vdu_connection_params.items()})

    def __getattr__(self, name):
        return getattr(self._vdu_connection, name)

    def _setup(self):
        logger.debug("connecting: {vdu_connection_params}".format(
            vdu_connection_params=self._vdu_connection_params))
        self._vdu_connection = self._create_vdu_connection(
            vdu_connection_params=self._vdu_connection_params)

    def _teardown(self):
        logger.debug("disconnecting: {vdu_connection_params}".format(
            vdu_connection_params=self._vdu_connection_params))
        try:
            self._vdu_connection.disconnect()
        except Exception as e:
            logger.debug("disconnecting failed due to {exception!r}".format(exception=e))
